  couplesEm: { en: 'agree', ta: 'ஒத்துப்போகிறீர்கள்', hi: 'एकमत हैं' },
  answeredOn: { en: 'Each of you answered privately on {date}. This shows only whether your answers matched — never who said what.', ta: 'நீங்கள் ஒவ்வொருவரும் {date} அன்று தனியாகப் பதிலளித்தீர்கள். உங்கள் பதில்கள் பொருந்தினவா என்பதை மட்டுமே இது காட்டும் — யார் என்ன சொன்னார்கள் என்பதை ஒருபோதும் அல்ல.', hi: 'आप दोनों ने {date} को अलग-अलग जवाब दिए। यह सिर्फ़ दिखाता है कि जवाब मिले या नहीं — कभी यह नहीं कि किसने क्या कहा।' },
  agreeOn: { en: 'You agree on {a} of {b} themes. The two where you differ are good places to start a State of Us.', ta: '{b} கருப்பொருள்களில் {a}-இல் நீங்கள் ஒத்துப்போகிறீர்கள். வேறுபடும் இரண்டும் ஒரு State of Us உரையாடலைத் தொடங்க நல்ல இடங்கள்.', hi: '{b} में से {a} विषयों पर आप एकमत हैं। जिन दो पर आप अलग हैं, वहीं से State of Us शुरू करना अच्छा रहेगा।' },
  themesAria: { en: 'Couples Check themes', ta: 'தம்பதி சோதனைக் கருப்பொருள்கள்', hi: 'कपल्स चेक के विषय' },
