  invited: { en: 'Invitation sent to {name}. It expires in 7 days.', ta: '{name}-க்கு அழைப்பு அனுப்பப்பட்டது. 7 நாட்களில் காலாவதியாகும்.', hi: '{name} को न्योता भेजा गया। यह 7 दिन में ख़त्म होगा।' },
